// ALT-065: chegada no CoperXII (vem do GestorDeCirculacao.para_coperXXI)
if (agent instanceof Trem) {
	Vagao v = ((Trem) agent).getPrimeiroVagao();
	if (v != null) {
		ferrovia_em_atendimento = v.ferrovia;
		produto_em_atendimento  = v.segmento;
	}
}
traceln(String.format("[%.1f][CoperXII][chegada] trem=%d carros=%d", time(), agent.getId(), ((Trem) agent).size()));

// ALT-076: com lote_b e lote_a cheios, o grupo fica na moega
if ("moega".equals(_grupo_linha)) grupo_na_moega.take(agent);
else                              ir_vazios.take(agent);

// ALT-069: no alívio, o acoplar_b/a devolve a loco do alívio já engatada no lote
if ("b".equals(etapa_alivio)) {
	lote_vazios_b = null;
	alivio_seguir((Trem) agent);
} else if ("a".equals(etapa_alivio)) {
	lote_vazios_a = null;
	alivio_seguir((Trem) agent);
} else {
	chegou_vazios.take(agent);
}

// ALT-073: o lote 2 é o trem original (sai pelo out) e espera no Wait espera_segunda_parte
lote_segunda_parte = (Trem) train;
traceln(String.format("[%.1f][CoperXII][corte_lotes] trem=%d lote1=%d carros", time(), train.getId(), get_carros_ate_segunda_loco((Trem) train)));

// ALT-076: fim do lote; a segunda parte vira lote_em_descarga e começa já se ainda faltam vazios para o alívio de 41
trocar_lote_em_descarga();
if (get_espaco_vazios() > 0) iniciar_proximo_lote();
traceln(String.format("[%.1f][CoperXII][vazios] trem=%d lote terminou: moega liberada", time(), agent.getId()));

// ALT-076: lote terminou na moega
trocar_lote_em_descarga();
if (get_espaco_vazios() > 0) iniciar_proximo_lote();
traceln(String.format("[%.1f][CoperXII][resto] trem=%d lote terminou na moega: moega liberada", time(), agent.getId()));

// ALT-076: guarda o lote da moega, confere se fechou 41 e solta o resto do lote
estoque_moega.block();
entrar_estoque_moega.take(agent);
verificar_alivio();
aguarda_grupo.unblock();

main().gestorDeAlivios.retornar_alivio.take(agent);
// ALT-070/071/073: linhas aliviadas: o lote_em_descarga (antiga segunda parte) começa
aguardando_alivio = false;
fazendoAlivio = false;
liberar_espaco_vazios();
iniciar_proximo_lote();

// ALT-076: o acoplar_moega serve ao alívio e ao grupo que completa o lote da moega
if ("moega".equals(etapa_alivio)) {
	lote_vazios_moega = null;
	alivio_seguir((Trem) agent);
} else {
	moega_guardar.take(agent);
}

// ALT-069: no alívio, o acoplar_b/a devolve a loco do alívio já engatada no lote
if ("b".equals(etapa_alivio)) {
